      :root {
        Color-scheme: light dark;
        supported-color-schemes:light dark;
      }
       /* Override Android Gmail */
      u + .body .tp_header {
        mix-blend-mode:screen;
      }

      u + .body tp_header_div {
        mix-blend-mode:difference;
      }

      
        @font-face {
          font-family: 'Optimistic Text Normal';
          font-style: normal;
          font-weight: normal;
          src: url(https://static.xx.fbcdn.net/rsrc.php/yd/r/vu9QUYy2ngT.woff2) format('woff2')
        }

        @font-face {
          font-family: 'Optimistic Display';
          font-style: normal;
          font-weight: normal;
          src: url(https://static.xx.fbcdn.net/rsrc.php/yL/r/jfwoHaS3i0K.woff2) format('woff2')
        }
        

      a {
        color: #344854;
      }

      ul {
        color: inherit !important;
        list-style-type: disc !important;
      }

      .tp_headline {
          color: #1C2B33;
        }

        .dark-image {
          display: none;
          mso-hide: all;
        }

        [data-ogsb] .tp_content .bg_meta-gray, .tp_content .bg_meta-gray {
          background-color: #F1F4F7;
        }

        [data-ogsb] .tp_content .bg_fb-gray, .tp_content .bg_fb-gray {
          background-color: #FBF9F6;
        }

        [data-ogsb] .tp_content .bg_ig-gray, .tp_content .bg_ig-gray {
          background-color: #F1F4F7;
        }

        [data-ogsb] .tp_content .bg_ws-gray, .tp_content .bg_ws-gray{
          background-color: #FCF5EB;
        }

        [data-ogsb] .tp_content .bg_msg-gray, .tp_content .bg_msg-gray {
          background-color: #F8F8F8;
        }

        [data-ogsb] .tp_content .bg_ig-orange, .tp_content .bg_ig-orange {
          background-color: #FF7A00;
        }

        [data-ogsb] .tp_content .bg_ig-pink, .tp_content .bg_ig-pink {
          background-color: #FF0069;
        }

        [data-ogsb] .tp_content .bg_ig-purple, .tp_content .bg_ig-purple {
          background-color: #7638FA;
        }

      @media (prefers-color-scheme: dark ) {
        /* Override body bg in dark mode */

        a {
          color: #FFF;
        }

        .tp_body {
          background-color: #283943 !important;
          color: #F1F4F7;
        }

        .tp_content table,
        .tp_content td {
          background-color: #1C2B33 !important;
          color: #F1F4F7;
        }

        .tp_content h1,
        .tp_content h2,
        .tp_content p,
        .tp_content span,
        .tp_content .tp_paragraph,
        .tp_content b,
        .tp_content div,
        .tp_headline {
          color: #F1F4F7 !important;
        }

        .tp_content .receipt-label {
          color: #A7B3BF !important;
        }

        .tp_content .receipt-value,
        .tp_content .receipt-link {
          color: #F1F4F7 !important;
        }

        .tp_content .receipt-divider {
          border-color: #465A69 !important;
        }

        .tp_content .email-table,
        .tp_content .email-table table,
        .tp_content .email-table td {
          background: #344854 !important;
        }

        .tp_header {
          background-color: #323232 !important;
          display: none !important;
        }
        .tp_dark-header {
          background-color: #283943 !important;
          display: block !important;
        }

        .tp_dark-header .dark-image,
        .tp_header .light-image {
            margin-left: auto;
            margin-right: auto;
        }

        .tp_dark-header .dark-image {
          background: none !important;
        }

        .tp_footer{
          background-color: #283943 !important;
          color: #F1F4F7 !important;
        }

        /* Shows dark mode images */
        .dark-image {
          display: block !important;
        }

        /* Hides light mode images */
        .light-image {
          display: none !important;
        }

        [data-ogsb] .tp_content .bg_meta-gray,
        [data-ogsb] .tp_content .bg_meta-gray td,
        .tp_content .bg_meta-gray td,
        .tp_content .bg_meta-gray {
          background-color: #344854 !important;
        }

        [data-ogsb] .tp_content .bg_fb-gray,
        [data-ogsb] .tp_content .bg_fb-gray td,
        .tp_content .bg_fb-gray, .tp_content .bg_fb-gray td, {
          background-color: #303030 !important;
        }

        [data-ogsb] .tp_content .bg_ig-gray,
        [data-ogsb] .tp_content .bg_ig-gray td,
        .tp_content .bg_ig-gray, .tp_content .bg_ig-gray td {
          background-color: #262626 !important;
        }

        [data-ogsb] .tp_content .bg_ws-gray,
        [data-ogsb] .tp_content .bg_ws-gray td,
        .tp_content .bg_ws-gray,
        .tp_content .bg_ws-gray td{
          background-color: #111B21 !important;
        }

        [data-ogsb] .tp_content .bg_msg-gray,
        [data-ogsb] .tp_content .bg_msg-gray td,
        .tp_content .bg_msg-gray, .tp_content .bg_msg-gray td {
          background-color: #303030 !important;
        }

        [data-ogsb] .tp_content .bg_ig-orange,
        [data-ogsb] .tp_content .bg_ig-orange td,
        .tp_content .bg_ig-orange, .tp_content .bg_ig-orange td {
          background-color: #FF7A00 !important;
        }

        [data-ogsb] .tp_content .bg_ig-pink,
        [data-ogsb] .tp_content .bg_ig-pink td,
        .tp_content .bg_ig-pink, .tp_content .bg_ig-pink td {
          background-color: #FF0069 !important;
        }

        [data-ogsb] .tp_content .bg_ig-purple,
        [data-ogsb] .tp_content .bg_ig-purple td,
        .tp_content .bg_ig-purple, .tp_content .bg_ig-purple td {
          background-color: #7638FA !important;
        }

        .tp_content .tp_button {
          background: #0064E0 !important;
        }

        .tp_content .tp_link {
          color: #FFF !important;;
        }

        .tp_content .tp_button.no-fill {
          background: inherit !important;
        }

        .tp_content .tp_button td, .tp_button td {
          background: none !important;
          background-color: inherit !important;
          color: #F1F4F7 !important
        }

        .tp_content .tp_button a {
          color: #F1F4F7 !important
        }

      }

      [data-ogsb] .tp_header {
        display: none !important;
      }

      [data-ogsb] .tp_dark-header {
        display: block !important;
      }

      [data-ogsc] .tp_body {
        background-color: #283943 !important;
        color: #FFF;
      }

      [data-ogsc] .tp_content .receipt-label {
        color: #A7B3BF !important;
      }

      [data-ogsc] .tp_content .receipt-value,
      [data-ogsc] .tp_content .receipt-link {
        color: #F1F4F7 !important;
      }

      [data-ogsc] .tp_content .receipt-divider {
        border-color: #465A69 !important;
      }

      [data-ogsc] .dark-image {
            display: block !important;
            margin-left: auto;
            margin-right: auto;
      };
      [data-ogsc] .light-image {
              display: none !important;
              margin-left: auto;
              margin-right: auto;
